export const sourcePages = {
  "72": "<h2>72</h2>\n<h3><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">イタリア・ドイツの統一</strong></span></h3>\n<p>みんなもよく知っているヨーロッパの国のうち、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">19世紀後半までなかった国</strong></u>があるんだよ。それが<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イタリアとドイツ</strong></u>だ。どちらもバラバラな状態だったんだけど、19世紀後半に統一されたんだよ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリアの統一</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツの統一</strong></span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <strong class=\"source-bold\">統一以前のイタリア</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">73〜75ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <strong class=\"source-bold\">統一以前のドイツ</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">80〜83ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <strong class=\"source-bold\">サルデーニャ王国の統一運動</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">75〜77ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <strong class=\"source-bold\">普墺戦争と普仏戦争</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">83〜87、89ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <strong class=\"source-bold\">イタリア王国の成立</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">77〜80ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">6</span> <strong class=\"source-bold\">統一後のドイツ</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">89〜92ページ</span></td></tr></tbody></table></div>\n<blockquote><p>みんなが知っている形のイタリアとドイツは、19世紀までなかったんだよ</p></blockquote>\n<p>「ヨーロッパの国を知ってる順にあげてごら〜ん」って言われた時に、どこの国が出てくるかな？　もちろん、人それぞれだとは思うけど、「イギリス、フランス……」って始まって多分10コ以内、いや5コ以内には「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ドイツ</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イタリア</strong></u>」って出てくるんじゃないかな？　サッカー強いしさ。イタリアは観光でも人気だもんね。でも、そんな<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イタリアもドイツも、現在のように統一された国になったのは19世紀後半</strong></u>！　まだできてから150年くらいだよ。似ているようでかなり違う2つの国の統一は、どうやって進んだんだろ？</p>\n<p>じゃあ、イタリアとドイツの統一の始まり〜。</p>",
  "73": "<h2>73</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">統一以前のイタリア</u></p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">イタリアの統一</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <strong class=\"source-bold\">統一以前のイタリア</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">そもそも、イタリアってどこ？　イタリアの統一って何すりゃいいのさ？</strong></span></h4>\n<p>今は当たり前のように「<strong class=\"source-bold\">イタリア</strong>」って言ってるけど、<strong class=\"source-bold\">イタリアが統一されたのは1861年</strong>なんだよね。じゃあそれ以前にちゃんと統一されてたのって、いつまでだろ？　思い出せるかな？　外から攻め込まれたのを抜かすと……<strong class=\"source-bold\">ローマ帝国</strong>だよ。まあ、東西に分裂したから<strong class=\"source-bold\">西ローマ帝国</strong>だね。その後<strong class=\"source-bold\">東ゴート王国</strong>もできるけど、これは<strong class=\"source-bold\">ゲルマン人の国</strong>だからイタリア人じゃない。さらに、イタリアのど真ん中にできた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローマ教皇領</strong></span>】によって、8世紀以降は<strong class=\"source-bold\">南北に分断</strong>されちゃった……。だって教皇領に手を出したら<ruby>天罰<rt>てんばつ</rt></ruby>が下る。しかも、イタリアを支配していた<strong class=\"source-bold\">カロリング朝も875年に断絶</strong>。ここからずっと分裂が続くから、ヨーロッパのほかの国の人はもちろん、イタリア人自身にも「<strong class=\"source-bold\">イタリア</strong>」っていう<strong class=\"source-bold\">国の感覚はない</strong>！　もちろん、現在のような意味での「<strong class=\"source-bold\">イタリア人</strong>」って<strong class=\"source-bold\">感覚もない</strong>んだよね。</p>\n<p>じゃあ、ウィーン体制下でのイタリア（国じゃなくて地理的な意味でのイタリア半島ってことね）の状況を確認しておこう。</p>\n<h4><strong class=\"source-bold\">〈ウィーン体制下のイタリア半島〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">スイス</strong></td><td><strong class=\"source-bold\">オーストリア帝国</strong></td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td><td>ロンバルディア（墺）</td></tr><tr><td>ヴェネツィア（墺）</td><td><strong class=\"source-bold\">パルマ</strong></td></tr><tr><td><strong class=\"source-bold\">モデナ</strong></td><td><strong class=\"source-bold\">サルデーニャ王国</strong></td></tr><tr><td><strong class=\"source-bold\">トスカナ大公国</strong></td><td><strong class=\"source-bold\">教皇領</strong></td></tr><tr><td>コルシカ島（仏）</td><td>サルデーニャ島</td></tr><tr><td><strong class=\"source-bold\">両シチリア王国</strong>（ブルボン朝）</td><td></td></tr></tbody></table></div>\n<blockquote><p>こんだけバラバラじゃ、一つの国って感覚がないのも当たり前だね</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "74": "<h2>74</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>まず<strong class=\"source-bold\">北イタリア</strong>では、大国<strong class=\"source-bold\">オーストリア</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロンバルディア</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェネツィア</strong></span>を支配していて、<strong class=\"source-bold\">オーストリアとフランス</strong>に挟まれる形で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サルデーニャ王国</strong></span>があるね。ウィーン議定書で<strong class=\"source-bold\">サヴォイアとジェノヴァを獲得</strong>したから、<strong class=\"source-bold\">サルデーニャ島</strong>と合わせればイタリアのなかでは一番強かったけど、しょせんヨーロッパでは弱小国だよ。そして、<strong class=\"source-bold\">中部イタリア</strong>には問題の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領</strong></span>。これがあるからイタリアは<strong class=\"source-bold\">南北に分断</strong>されてるんだ。そして、教皇領の北側の小さな君主国（パルマ、モデナ、トスカナ大公国など）は、たいてい<strong class=\"source-bold\">ハプスブルク家</strong>（つまり<strong class=\"source-bold\">オーストリア</strong>）<strong class=\"source-bold\">と仲がいい</strong>。さらに<strong class=\"source-bold\">南イタリア</strong>にある<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">両シチリア王国</strong></span>は、これまた<strong class=\"source-bold\">ブルボン朝</strong>（スペイン系）の支配……。ってことは、<strong class=\"source-bold\">イタリア半島のほとんどが外国の支配下</strong>にあるってことだよ。これを統一するって、いったいどうすりゃいいのさ？</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">イタリアの統一</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サルデーニャ王国</strong></span>による統一運動</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>国王：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィットーリオ＝エマヌエーレ2世</strong></span>、首相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カヴール</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア戦争</strong></span>に参戦［1855］……<strong class=\"source-bold\">英仏側で参戦</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><strong class=\"source-bold\">プロンビエール<ruby>密約<rt>みつやく</rt></ruby></strong>［1858］……仏の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span>の支援を得る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア統一戦争</strong></span>［1859］……<strong class=\"source-bold\">オーストリアとの戦争</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ナポレオン3世が裏切り</strong>、フランスが単独<ruby>講和<rt>こうわ</rt></ruby>（<strong class=\"source-bold\">ヴィラフランカ条約</strong>）</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロンバルディア</strong></span>は獲得、<strong class=\"source-bold\">ヴェネツィアはオーストリア領のまま</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中部イタリア<ruby>併合<rt>へいごう</rt></ruby></strong></span>［1860］<span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サヴォイア</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニース</strong></span>を<strong class=\"source-bold\">フランスに<ruby>割譲<rt>かつじょう</rt></ruby></strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガリバルディ</strong></span>を中心とする愛国派の統一運動</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>千人隊<rt>せんにんたい</rt></ruby></strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">赤シャツ隊</strong></span>】の結成［1860］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シチリア島<ruby>占領<rt>せんりょう</rt></ruby></strong></span>、さらに南イタリアに上陸し<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">両シチリア王国征服</strong></span>［1860］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span>南イタリアで<strong class=\"source-bold\">住民投票</strong>が実施され、サルデーニャ王国への併合が決定</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア王国</strong></span>の成立［1861］……ヴェネツィアと教皇領を除き統一達成</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>国王：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィットーリオ＝エマヌエーレ2世</strong></span>、首相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カヴール</strong></span></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェネツィア併合</strong></span>［1866］……<strong class=\"source-bold\"><ruby>普墺<rt>ふおう</rt></ruby>戦争</strong>に乗じて併合</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領占領</strong></span>［1870］……<strong class=\"source-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong>に乗じて占領</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">未回収のイタリア</strong></span>」……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリエステ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イストリア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南チロル</strong></span>など</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">2つの方向があったイタリア統一運動</strong></span></h4>\n<p>こんな状況だったから、「イタリアの統一って何？」って聞かれても、イタリア人自身もよくわからない。でも、<strong class=\"source-bold\">外国に支配されるのはイヤ</strong>だから、ウィーン</p>",
  "75": "<h2>75</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">サルデーニャ王国の統一運動</u></p>\n<p>体制下では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルボナリ</strong></span>が<ruby>蜂起<rt>ほうき</rt></ruby>した。でも全部<ruby>潰<rt>つぶ</rt></ruby>されちゃったから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マッツィーニ</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年イタリア</strong></span>をつくったよね。<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第1回</strong></span>でやったのをちょっと思い出してみよう！　<strong class=\"source-bold\">1848年の二月革命の影響</strong>で、イタリアでは2つの大きな動きがあったよね。一つは、サルデーニャ王<strong class=\"source-bold\">カルロ＝アルベルト</strong>の<strong class=\"source-bold\">対オーストリア戦争</strong>、もう一つは、<strong class=\"source-bold\">マッツィーニ</strong>が建てた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローマ共和国</strong></span>。どちらも<strong class=\"source-bold\">イタリア統一を目指す</strong>方向は同じなんだけど、<strong class=\"source-bold\">目標が違う</strong>のわかる？　かなり根本的な問題だよ。サルデーニャ王国が目指しているのは「<strong class=\"source-bold\">イタリア王国</strong>」だ。そして、マッツィーニらは「<strong class=\"source-bold\">イタリア共和国</strong>」をつくりたい！　国王はいらないんだよ。つまり「<strong class=\"source-bold\">王政にするか、共和政にするか</strong>」。どっちになるんだろう？</p>\n<blockquote><p>「イタリア王国」か「イタリア共和国」か……難しい問題だね</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <strong class=\"source-bold\">サルデーニャ王国の統一運動</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イタリア統一に向かって、サルデーニャ王国が動き出した！</strong></span></h4>\n<p>統一に向かってまず動き出したのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サルデーニャ王国</strong></span>だ。カルロ＝アルベルトが退位すると、息子の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィットーリオ＝エマヌエーレ2世</strong></span>が国王となり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カヴール</strong></span>を首相に登用した。この二人がここから<strong class=\"source-bold\">イタリア統一運動の中心</strong>になるんだけど、まず考えなきゃいけないのは「<strong class=\"source-bold\">なんでこれまでの統一運動が失敗ばかりだったのか？</strong>」ということだ。ん？　弱いから？……とか言わない。</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カヴール</strong></span>は、若いころイギリスとフランスを旅行し、特に<strong class=\"source-bold\">イギリスの自由主義経済と議会主義の影響を受ける</strong>一方で、「愛国者のやっているイタリア統一運動は現実的じゃない。むしろ<strong class=\"source-bold\">独立とピエモンテ</strong>（<strong class=\"source-bold\">サルデーニャ王国</strong>）<strong class=\"source-bold\">の拡大</strong>を目指すべき」と確信したんだ。だって、大国フランスをこの目で見ちゃったんだもん。今のままじゃ、サルデーニャ王国は弱すぎるよ。</p>\n<p>そこで<strong class=\"source-bold\">カヴールは国内の近代化を進めた</strong>。まずは教会の財産を没収し、それを財源に<strong class=\"source-bold\">産業振興や鉄道建設</strong>、それに<strong class=\"source-bold\">軍制改革</strong>をやった。これでオーストリアに……って、勝てるわけない。だって、サルデーニャ軍はこの時点で6万人ちょい、対するオーストリア軍は一声で20万人くらいは出てくる。ていうか無理でしょ……。だったら<strong class=\"source-bold\">誰かに助けてもらえばいい</strong>。オーストリアの敵といえば……<strong class=\"source-bold\">フランス</strong>！　でもどうやって味方にすればいいんだろ？</p>\n<p>そこにすごいチャンスが訪れた。それが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア戦争</strong></span>だ！　<strong class=\"source-bold\">カヴール</strong>は考えた。「フランスの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span>は、ヨーロッパの勢力<ruby>均衡<rt>きんこう</rt></ruby>を破って<strong class=\"source-bold\">フランスの強大化を狙っている</strong>。これを利用して<strong class=\"source-bold\">対オーストリア戦争での協力を得る</strong>！」ってことだ。こうしてサルデーニャ王国は<strong class=\"source-bold\">クリミア戦争に英仏側で参戦</strong>、なけなしの軍を1万5000人も出したんだよ。カヴールは、戦後のパリ<ruby>講和<rt>こうわ</rt></ruby>会議に出席して、<strong class=\"source-bold\">サルデーニャの国際的地位を上げて</strong>、さらに<strong class=\"source-bold\">英仏を味方にしようとした</strong>。ただ、ちょっと気合</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "76": "<h2>76</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>い入りすぎちゃったんだろうなぁ。カヴールの反オーストリアの姿勢が激しくて、イギリスには警戒された。これは、フランスに期待するしかない……。</p>\n<p>そこでカヴールは<strong class=\"source-bold\">フランスのナポレオン3世に接近</strong>したんだよ。一方の<strong class=\"source-bold\">ナポレオン3世</strong>も偉大な叔父ナポレオン1世の栄光を復活したいから、<strong class=\"source-bold\">サルデーニャ王国を拡大させてフランスの<ruby>衛星国<rt>えいせいこく</rt></ruby>にして</strong>、教皇の保護者としてイタリア各地にも支配を伸ばして……って、夢が広がってる。こうして、<strong class=\"source-bold\">カヴールとナポレオン3世</strong>の間で<strong class=\"source-bold\">プロンビエール<ruby>密約<rt>みつやく</rt></ruby></strong>が結ばれたよ。このなかで、<strong class=\"source-bold\">フランスがサルデーニャ王国の対オーストリア戦争を支援</strong>すること、代償として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サヴォイア</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニース</strong></span>をフランスに<ruby>割譲<rt>かつじょう</rt></ruby>すること、さらに入試レベルじゃないけど、教皇領や両シチリア王国を現状のまま残すことが決められたんだ。</p>\n<blockquote><p>フランスに頼らないと統一はできないって……なかなか辛い状況だな</p></blockquote>\n<h4>＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">α</strong></span><u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">ちょっと寄り耳</strong></u></h4>\n<blockquote><p>イタリア統一運動の中心はカヴールやガリバルディだけど、愛国心を盛り上げたという点では、僕の好きな作曲家ヴェルディの果たした役割も大きかった。ヴェルディが生まれたのは1813年、ちょうどワーテルローの戦いの年だ。</p>\n<p>彼が初めて大衆的な人気を得た作品は、バビロン<ruby>捕囚<rt>ほしゅう</rt></ruby>に苦しむヘブライ人を題材とした「ナブッコ」。イタリア人は外国の支配に苦しむ自分たちを、作品中のヘブライ人に重ね合わせ、故郷への想いを歌った合唱「わが想いよ、黄金の翼に乗って」を、まだ実現していない祖国イタリアへの想いに重ねて歌ったんだ。現在でもこの歌はイタリアの第2の国歌といわれているよ。その後、「シチリアの<ruby>晩鐘<rt>ばんしょう</rt></ruby>」など愛国心を高める作品を数多く作り名声を高めたヴェルディは、感情の<ruby>湧<rt>わ</rt></ruby>き上がるイタリア・オペラを確立、現在でも上演され続けるくらい人気の作曲家になった。「<ruby>椿姫<rt>つばきひめ</rt></ruby>」の乾杯の歌や、サッカーでよく流れる「アイーダ」の<ruby>凱旋<rt>がいせん</rt></ruby>行進曲なんかは、みんなも耳にしたことがあるんじゃないかな？　ちなみに、「アイーダ」はスエズ運河開通を記念して上演されたオペラだよ。</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イタリア統一戦争が<ruby>勃発<rt>ぼっぱつ</rt></ruby>したけど……フランスに裏切られた！</strong></span></h4>\n<p>こうして<strong class=\"source-bold\">オーストリアとサルデーニャ王国</strong>の間で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア統一戦争</strong></span>が始まったんだけど、オーストリアにも誤算があった。イギリスの動きを警戒してナポレオン3世が迷っているんじゃ？　と思ったんだけど、いきなり12万人の<strong class=\"source-bold\">フランス軍が出兵してきた</strong>。そして、19世紀最大の戦闘となった<strong class=\"source-bold\">ソルフェリーノの戦い</strong>では、フランス、サルデーニャが12時間にわたる戦闘の末、<strong class=\"source-bold\">オーストリアを破った</strong>。ちなみにこの時、ナイティンゲールの影響を受けて戦場で兵士の救護活動をしていたスイス人の<strong class=\"source-bold\">アンリ＝デュナン</strong>が、のちに<strong class=\"source-bold\">国際赤十字</strong>を設立することになるよ。</p>",
  "77": "<h2>77</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イタリア王国の成立</u></p>\n<p>オーストリアに勝ったというニュースが広がった<strong class=\"source-bold\">イタリアでは、愛国運動が盛り上がった</strong>よ。「このままいけば外国支配から独立できるのでは」と、<strong class=\"source-bold\">中部イタリア</strong>、さらに教皇領のなかでも<strong class=\"source-bold\">民衆の反乱</strong>が起き始めた。焦ったのは<strong class=\"source-bold\">ナポレオン3世</strong>だ。だって彼は、<strong class=\"source-bold\">自分自身がイタリアへの影響を持ちたい</strong>だけで、サルデーニャ王国には北イタリアの一部しか渡すつもりはない。にもかかわらず、カヴールが密かに中部イタリアへの勢力拡大を目論んでるようだし、しかも北方のプロイセンの動きが怪しい……。こうして、<strong class=\"source-bold\">ナポレオン3世は勝手にオーストリアと<ruby>講和<rt>こうわ</rt></ruby>を結んで<ruby>撤退<rt>てったい</rt></ruby></strong>した（<strong class=\"source-bold\">ヴィラフランカ条約</strong>）。これを見たカヴールは怒った！　かといって単独でオーストリアと戦っても勝てないから、やむなく休戦を受け入れた。だから、<strong class=\"source-bold\">サルデーニャ王国はオーストリアから</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロンバルディア</strong></span><strong class=\"source-bold\">を獲得</strong>するにとどまり、<strong class=\"source-bold\">ヴェネツィアはオーストリア領のまま</strong>残ったんだよ。しかし、このフランスの裏切りはイタリア人を怒らせたんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">なんでこんなに大国に<ruby>翻弄<rt>ほんろう</rt></ruby>されるんだ！　中部イタリアの人びとが怒った</strong></span></h4>\n<p>フランスの裏切りを見たイタリア人たちは「なんで、イタリアは大国に翻弄されてばっかりなんだ〜」って怒り、愛国心を強めていった。しかも、<strong class=\"source-bold\">イタリア統一戦争中に中部イタリア小国家の君主たちが次々と<ruby>亡命<rt>ぼうめい</rt></ruby></strong>していたから、もはや住民たちを抑えるものは何もない！　彼らは「<strong class=\"source-bold\">サルデーニャと<ruby>合併<rt>がっぺい</rt></ruby></strong>して、イタリアを大きくしよう！」って言い出した。もちろん、カヴールがウラで動いてるんだけどさ。こうして1860年、住民投票によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中部イタリア</strong></span>の<strong class=\"source-bold\">サルデーニャ王国への<ruby>併合<rt>へいごう</rt></ruby></strong>が決まったよ。</p>\n<p>ただ、これを見た<strong class=\"source-bold\">ナポレオン3世</strong>は「サルデーニャのくせに生意気な」と思ったから「<strong class=\"source-bold\">中部イタリアの併合を認めてやるかわりに</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サヴォイア</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニース</strong></span>をよこせ！」って言い始めた。うーん、苦渋の決断を迫られてる。だってサヴォイアって王家の発祥の地だし、西からの防衛の拠点だもん。でも、<strong class=\"source-bold\">これを認めないとフランスが完全に敵になる</strong>。カヴールも受け入れるしかなかったんだね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <strong class=\"source-bold\">イタリア王国の成立</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">統一運動のもう一つの動き。いよいよガリバルディが動いた！</strong></span></h4>\n<p>ここまでの統一運動でサルデーニャ王国が拡大し、残すは<strong class=\"source-bold\">オーストリア支配下の</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェネツィア</strong></span>、<strong class=\"source-bold\">フランスが保護する</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領</strong></span>、<strong class=\"source-bold\">ブルボン朝</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">両シチリア王国</strong></span>だけになった。ていうか、どこも大国を敵に回さないと取れないところばかりだ。今のサルデーニャには、全部ムリだよ。ここで動き出したのが<strong class=\"source-bold\">民衆主導の統一</strong>、かつての<strong class=\"source-bold\">青年イタリア</strong>の連中だ。中心となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガリバルディ</strong></span>は、<strong class=\"source-bold\">青年イタリア</strong>に参加し、1849年の<strong class=\"source-bold\">ローマ共和国の防衛</strong>に力を尽くし、<strong class=\"source-bold\">イタリア統一戦争</strong>でも<strong class=\"source-bold\"><ruby>義勇軍<rt>ぎゆうぐん</rt></ruby></strong>「アルプス狙撃隊」を率いた統一運動の英雄だよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "78": "<h2>78</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>1860年、<strong class=\"source-bold\">シチリア島でブルボン朝に対する農民反乱</strong>が起きたというニュースを聞いた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガリバルディ</strong></span>ら愛国者たちは「民衆反乱を拡大して、今こそイタリアを解放する時がきた！」って盛り上がった。彼らは<strong class=\"source-bold\">民主的なイタリア統一国家をつくりたい</strong>から、カヴールから主導権を奪いたい。ガリバルディは「今こそイタリア国民の統一のために立ち上がれ」とジェノヴァで<strong class=\"source-bold\"><ruby>義勇軍<rt>ぎゆうぐん</rt></ruby></strong>を集めたんだ。こうして結成されたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>千人隊<rt>せんにんたい</rt></ruby></strong></span>、通称<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">赤シャツ隊</strong></span>だ。統一への情熱だけは誰にも負けない！　彼らがシチリア島に向かって出兵すると、あくまで<strong class=\"source-bold\">サルデーニャ王国の拡大で統一したいカヴールが妨害</strong>してきた。でも、動き出した歴史の波は止められないよ。</p>\n<p><strong class=\"source-bold\">シチリア島に上陸</strong>してからのガリバルディは、奇跡的な勝利を続けたよ。彼らは、壊れかけてる銃に銃剣をつけただけのショボい武器しか持ってなかったけど、ガリバルディの情熱に勇気をもらった<strong class=\"source-bold\">シチリア住民がどんどん軍に参加してくる</strong>。もう誰にも止められない。こうして1860年6月には<strong class=\"source-bold\">パレルモを解放</strong>し、<strong class=\"source-bold\">ガリバルディ</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シチリア島を<ruby>占領<rt>せんりょう</rt></ruby></strong></span>した。そして、8月に<strong class=\"source-bold\">南イタリアに上陸</strong>すると、さらに義勇軍が増え続けてついに5万人！　こうして<strong class=\"source-bold\">ナポリも制圧</strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南イタリア征服</strong></span>（<strong class=\"source-bold\">両シチリア王国の全土</strong>ってことね）を完成させたよ。</p>\n<h4><strong class=\"source-bold\">〈イタリアの統一〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">サヴォイア →仏へ</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ヴェネツィア併合［1866］</span></td></tr><tr><td>南チロル</td><td><strong class=\"source-bold\">オーストリア帝国</strong></td></tr><tr><td>イストリア</td><td>トリエステ</td></tr><tr><td>○トリノ</td><td>○ジェノヴァ</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ニース →仏へ</span></td><td>コルシカ島（仏）</td></tr><tr><td>ローマ</td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ヴィットーリオ=エマヌエーレ2世の進路</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">教皇領併合［1870］</span></td><td>ナポリ</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ガリバルディの進路</span></td><td>シチリア島</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"pink\" data-source-border=\"red\" style=\"color:#f0a0a0;border:1px solid #e52715\">●</span> 未回収のイタリア</td><td></td></tr></tbody></table></div>\n<blockquote><p>やっと今のイタリアの形になるよ！　<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➜P.73</span>の地図と比べてみよう</p></blockquote>",
  "79": "<h2>79</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イタリア王国の成立</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">国王とガリバルディの握手……ついにイタリア統一だ！</strong></span></h4>\n<p>この動きを見た<strong class=\"source-bold\">カヴールはむちゃくちゃ焦った</strong>。彼らがこのまま「ローマに向かえ〜！」って<strong class=\"source-bold\">教皇領に攻め込んだら……間違いなくフランスを怒らせる</strong>。「やつらの動きを止めるしかない」と思ったカヴールは、ガリバルディを止めるために教皇領に<ruby>侵入<rt>しんにゅう</rt></ruby>することをナポレオン3世に連絡すると、国王<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィットーリオ＝エマヌエーレ2世</strong></span>が軍を率いて南下し、<strong class=\"source-bold\">教皇領の一部を占領</strong>しながらナポリの北方のテアーノまで進み、ここで<strong class=\"source-bold\">国王とガリバルディの会見</strong>がおこなわれたよ。</p>\n<p>この会見はイタリア統一を<ruby>象徴<rt>しょうちょう</rt></ruby>する場面として、ある種の神話として広まっているけど、実際には、保守派が実施を強行に主張した<strong class=\"source-bold\">住民投票で南イタリアのサルデーニャ王国への<ruby>併合<rt>へいごう</rt></ruby></strong>を決めて、<strong class=\"source-bold\">イタリア統一が実現した</strong>。ガリバルディは地中海の小さな島に移り、もう表舞台には出てこない。だって、ガリバルディが夢見ていたのとは違うイタリアが姿を現すんだもん。</p>\n<p>1861年、<strong class=\"source-bold\">トリノ</strong>を首都とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア王国</strong></span>が成立したよ。初代国王は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィットーリオ＝エマヌエーレ2世</strong></span>、首相は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カヴール</strong></span>だ。これって、単に<strong class=\"source-bold\">サルデーニャ王国が拡大しただけ</strong>でしょ。そう思った人……鋭い！　<strong class=\"source-bold\">統一後も制限選挙</strong>だったから民衆は政治に参加できないし、<strong class=\"source-bold\">農民にも土地は分配されない</strong>。つまり、統一したイタリアは民衆が夢見ていたものとは違っていた。だから「イタリアができたんじゃなくて、サルデーニャに占領された」って思った人もいたよ。そして<strong class=\"source-bold\">カヴール</strong>も、イタリア王国成立後、<strong class=\"source-bold\">わずか3カ月で急死</strong>してしまったんだ。</p>\n<blockquote><p>夢が破れた人たちのなかには、アメリカに移民した人もいるよ。それがアメリカの「新移民」ね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ヴェネツィアと教皇領の併合は、プロイセンのおかげ</strong></span></h4>\n<p>残るは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェネツィア</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領</strong></span>。<strong class=\"source-bold\">ヴェネツィアはオーストリア領、教皇領にはフランス軍がいる</strong>けど、まさかイタリアがフランスやオーストリアにケンカ売るのはムリ。のび太がジャイアンにケンカ売るようなもんだ。そんなイタリアにもチャンスがくる。それが<strong class=\"source-bold\">ドイツ統一を進める強国プロイセンの動き</strong>だ。</p>\n<p>当時、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン</strong></span>は<ruby>宰相<rt>さいしょう</rt></ruby>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>を中心にドイツ統一を進めていて、オーストリアとは統一の主導権をめぐって対立し、フランスのナポレオン3世はドイ</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">普</strong></span></td><td></td></tr><tr><td><strong class=\"source-bold\">普仏戦争</strong></td><td></td><td><strong class=\"source-bold\">普墺戦争</strong></td></tr><tr><td><strong class=\"source-bold\">仏</strong></td><td></td><td><strong class=\"source-bold\">墺</strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領占領</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">伊</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェネツィア併合</strong></span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "80": "<h2>80</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>ツの統一を望んでいなかった。ん？　<strong class=\"source-bold\">プロイセンの敵はオーストリアとフランス</strong>……おっ、<strong class=\"source-bold\">イタリアと一緒</strong>だね♪。<strong class=\"source-bold\">ビスマルク</strong>は戦争を有利にするために<strong class=\"source-bold\">イタリアに接近</strong>したから、イタリアには願ってもないチャンスがきたんだ。</p>\n<p>1866年、ビスマルクはイタリアと<ruby>密約<rt>みつやく</rt></ruby>を結び、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普墺<rt>ふおう</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝オーストリア戦争</strong></span>】で勝利したよ。ていうか、<strong class=\"source-bold\">プロイセンが勝った</strong>ってことは<strong class=\"source-bold\">イタリアも勝ち</strong>だよ。こうして、イタリアは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェネツィアを<ruby>併合<rt>へいごう</rt></ruby></strong></span>したんだ。さらに1870年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝フランス戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏戦争</strong></span>】が始まると、プロイセン軍の進撃で苦戦したフランスは<strong class=\"source-bold\">ローマ守備隊を本国に撤退させた</strong>。だって、ローマよりパリのほうが大事でしょ。これで喜んだのはイタリアだ。そのまま<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教皇領を<ruby>占領<rt>せんりょう</rt></ruby></strong></span>し、翌年には首都を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローマ</strong></span>に<ruby>遷<rt>うつ</rt></ruby>した。こうして、ほぼ現在と同じイタリアができたんだね。</p>\n<p>ただ<strong class=\"source-bold\">問題が2つ</strong>ある。一つは「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">未回収のイタリア</strong></span>」だ。<strong class=\"source-bold\">プロイセンに頼ってヴェネツィアを併合</strong>したけど、ビスマルクにはイタリアの都合なんてどうでもよかったんだよ。だからヴェネツィアの全部を占領する前に戦争が終わっちゃった。結局1870年の教皇領併合のあとも<strong class=\"source-bold\">オーストリア領のまま残った</strong>イタリア人居住地、具体的には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリエステ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イストリア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南チロル</strong></span>などがあって、これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">未回収のイタリア</strong></span>」と呼ばれているよ。</p>\n<p>もう一つが<strong class=\"source-bold\">ローマ教皇との問題</strong>だ。フランス軍が撤退したからといって、教皇自身はローマをイタリア王国にあげる気などさらさらなかったんだよ。でも併合されて<strong class=\"source-bold\">教皇領がなくなった</strong>から、完全にキレた。<strong class=\"source-bold\">教皇ピウス9世はイタリア王国を認めず</strong>に、国王ヴィットーリオ＝エマヌエーレ2世を<ruby>破門<rt>はもん</rt></ruby>すると「<strong class=\"source-bold\">ヴァチカンの<ruby>囚人<rt>しゅうじん</rt></ruby></strong>」と宣言して教皇庁に引きこもった。というか、イタリア人って<strong class=\"source-bold\">ほとんどがカトリック教徒</strong>だから、このあとずっと<strong class=\"source-bold\">イタリア王国と教皇の決定的な対立に悩まされる</strong>んだ。だって「イタリアにつくか、それとも教会につくか」っていう、答えの出ない二択を突きつけられたんだもんね。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">ドイツの統一</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <strong class=\"source-bold\">統一以前のドイツ</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">いったいどこまでがドイツ？　統一をめぐって対立する2大国</strong></span></h4>\n<p>続いて<strong class=\"source-bold\">ドイツの統一</strong>だよ。ドイツも19世紀後半までバラバラだったよね。中世以来の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>神聖<rt>しんせい</rt></ruby>ローマ帝国</strong></span>は、17世紀の三十年戦争以来、<strong class=\"source-bold\">帝国内の各<ruby>領邦<rt>りょうほう</rt></ruby></strong>（<strong class=\"source-bold\">要するに<ruby>諸侯<rt>しょこう</rt></ruby>ね</strong>）<strong class=\"source-bold\">に主権が認められた</strong>から、帝国内に小さい君主国が300近くもあったんだ。</p>\n<p>そして<strong class=\"source-bold\">ナポレオンの遠征</strong>によって<strong class=\"source-bold\">神聖ローマ帝国が消滅</strong>し、ウィーン体制下では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア</strong></span>を<ruby>盟主<rt>めいしゅ</rt></ruby>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ連邦</strong></span>ができた。ナポレオンの遠征によって領邦の数は減ったけど、まだ<strong class=\"source-bold\">35君主国</strong>もある！　しかも、かつて神聖ローマ皇帝だったオーストリアだけじゃなくて、北方の新興国<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン</strong></span>が強大化して、1834年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ<ruby>関税<rt>かんぜい</rt></ruby>同盟</strong></span>を結成していたね。つまり、<strong class=\"source-bold\">政治の主導権はオーストリア、経済の主</strong></p>",
  "81": "<h2>81</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">統一以前のドイツ</u></p>\n<p><strong class=\"source-bold\">導権はプロイセン</strong>が握ってるってことだ。うーん、これは絶対にモメる。実際、1848年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランクフルト国民議会</strong></span>でも、<strong class=\"source-bold\">オーストリアを中心とする</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大ドイツ主義</strong></span>と、<strong class=\"source-bold\">プロイセンを中心とする</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">小ドイツ主義</strong></span>の対立が起きたんだ。しかもこの両国、宗教も違うんだよ。<strong class=\"source-bold\">カトリックのオーストリア</strong>に対し、<strong class=\"source-bold\">プロテスタントのプロイセン</strong>……こりゃ、ドイツの統一もなかなか難しいね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">動き出したプロイセン！　ビスマルクの「<ruby>鉄血<rt>てっけつ</rt></ruby>政策」って？</strong></span></h4>\n<p>そんななかで動き出したのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン</strong></span>だ。国王の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム1世</strong></span>は<ruby>宰相<rt>さいしょう</rt></ruby>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>を登用したよ。<strong class=\"source-bold\">ビスマルク</strong>は<strong class=\"source-bold\">ユンカー</strong>の出身だから、カヴールとは違って自由主義なんて大キライな<strong class=\"source-bold\">超保守派</strong>！　国王が強いままのドイツを目標に、<strong class=\"source-bold\">軍備拡大によって統一を進めた</strong>んだ。</p>\n<p>宰相になってすぐに、<strong class=\"source-bold\">ビスマルク</strong>は軍事予算を否決した議会に対して「<strong class=\"source-bold\">議会を無視して軍備を拡大する！</strong>」って宣言しちゃった。「現在の大問題の解決は言論や多数決ではなく、<strong class=\"source-bold\">鉄と血</strong>によってのみ解決される」っていう有名な<strong class=\"source-bold\">鉄血演説</strong>は、「ドイツ統一は<strong class=\"source-bold\">議会での議論や話し合いじゃなくて、軍備拡大で実現</strong>する」って意味だもんね。これが有名な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">鉄血政策</strong></span>だ。もちろん議会だって反対したし、議会と政府の間で軍事予算の決定権をめぐる対立を引き起こしたよ（<strong class=\"source-bold\">プロイセン憲法論争</strong>）。この鉄血政策により国家予算をつぎこんで<strong class=\"source-bold\">軍需産業を発展させた</strong>から、プロイセンではのちに「死の商人」として有名になる大<ruby>財閥<rt>ざいばつ</rt></ruby><strong class=\"source-bold\">クルップ</strong>などが出現したよ。そして、ビスマルクはクルップに新型の<ruby>大砲<rt>たいほう</rt></ruby>なんかを開発させ、<strong class=\"source-bold\">軍の近代化</strong>を一気に進めたんだ。</p>\n<blockquote><p>「鉄血政策」ってのは「軍隊が強けりゃ誰も文句言えない！」って感じかな</p></blockquote>\n<p>ドイツ統一を目指す<strong class=\"source-bold\">プロイセンが倒さなきゃいけない国は2つ</strong>あったんだよ。まずは<strong class=\"source-bold\">ドイツ内部の主導権をめぐるオーストリアとの争い</strong>だ。もともと<strong class=\"source-bold\">オーストリアはドイツ連邦の議長国</strong>だし、もっとさかのぼると神聖ローマ皇帝！　順当にいけばオーストリアが統一の中心になってしまう。これをひっくり返すには戦争で勝つしかないだろ、ってのがビスマルクの考えだ。</p>\n<p>さらにフランス。<strong class=\"source-bold\">フランスにとっては</strong>、隣国のドイツがバラバラでいてくれたほうが、<strong class=\"source-bold\">自分の国の安全のためには都合がいい</strong>んだよ。しかも、皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span>は、叔父のナポレオン1世みたいに、大陸ヨーロッパの<ruby>覇権<rt>はけん</rt></ruby>を握りたいって思っているし、戦争で人気を取ろうとしている。やっぱ、これも倒すしかないでしょ。だから、<strong class=\"source-bold\">オーストリアとフランスを倒さなきゃ統一はできない</strong>。</p>\n<p>そしてさらに、もう一つの問題があるんだよ。それがウィーン体制以来の「<strong class=\"source-bold\">勢力<ruby>均衡<rt>きんこう</rt></ruby></strong>」の問題だ。<strong class=\"source-bold\">英・仏・墺・普・露の5大国</strong>の勢力均衡によってヨーロッパの秩序を維持しよう、って考え方はこの時代にもまだ生きていたから、プロイセンから</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "82": "<h2>82</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>戦争を仕掛けるのは、国際関係の上であまりよくない……。うーん、難しい課題がいっぱいだ。でもこれを全部なんとかしちゃうのがビスマルクのすごいところなんだ。</p>\n<p>まず、オーストリアとフランスに勝つには、<strong class=\"source-bold\">戦争の前に絶対に勝てるだけの準備をしてから開戦すればいい</strong>。当時プロイセンには陸軍が40万人以上いて、新型の兵器も揃えてる。しかも、開戦したらあっという間に移動できるように、<strong class=\"source-bold\">国境まで鉄道も建設した</strong>。さらに、戦争は自分から仕掛けるんじゃなくて相手から仕掛けさせるんだよ。「売られたケンカを買ったら、ボッコボコにしちゃった」っていうふうにね。そんなことできんの？……天才だからできる。というわけで、このあと<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普墺<rt>ふおう</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝オーストリア戦争</strong></span>】と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝フランス戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏戦争</strong></span>】という2つの戦争があるよ。</p>\n<h4><strong class=\"source-bold\">〈ドイツの統一〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>デンマーク</td><td>シュレスヴィヒ</td></tr><tr><td>ホルシュタイン</td><td>イギリス</td></tr><tr><td>○ベルリン</td><td>プロイセン王国</td></tr><tr><td>ロシア帝国</td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">スダンの戦い［1870］</span></td></tr><tr><td>○パリ</td><td>バイエルン</td></tr><tr><td>○プラハ</td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">サドヴァの戦い［1866］</span></td></tr><tr><td>○ウィーン</td><td>フランス</td></tr><tr><td>スイス</td><td>オーストリア帝国</td></tr><tr><td>サルデーニャ</td><td>スペイン</td></tr><tr><td>教皇領</td><td></td></tr><tr><td><span data-source-marker=\"line\" data-source-color=\"green\" style=\"color:#859476\">━</span> 1866年以前のドイツ連邦の境界線</td><td></td></tr><tr><td><span data-source-marker=\"dashed-line\" data-source-color=\"red\" style=\"color:#e52715\">┄</span> 北ドイツ連邦の境界線</td><td></td></tr></tbody></table></div>",
  "83": "<h2>83</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">普墺戦争と普仏戦争</u></p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">プロイセンによるドイツ統一</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>プロイセン国王<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム1世</strong></span>［位1861〜88］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>首相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>［任1862〜90］……「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>鉄血<rt>てっけつ</rt></ruby>政策</strong></span>」（<strong class=\"source-bold\">鉄は武器、血は兵士</strong>）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">普墺戦争</strong>【<strong class=\"source-bold\">プロイセン＝オーストリア戦争</strong>】</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュレスヴィヒ・ホルシュタイン問題</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デンマーク戦争</strong></span>……<strong class=\"source-bold\">オーストリアと共同出兵</strong>し、勝利</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span>両公国の<ruby>帰属<rt>きぞく</rt></ruby>とその処理をめぐり、ビスマルクが墺を挑発</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">普墺戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝オーストリア戦争</strong></span>】［1866］<span data-source-color=\"green\" style=\"color:#315837\">➜</span>プロイセンが勝利</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュレスヴィヒ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホルシュタイン</strong></span>は<strong class=\"source-bold\">プロイセンに<ruby>併合<rt>へいごう</rt></ruby></strong>。</p>\n<p><strong class=\"source-bold\">ドイツ連邦の解体、オーストリアをドイツ統一から排除</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ドイツ連邦</strong></span>成立［1867］……プロイセンを首長とする北ドイツの連合体</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">普仏戦争</strong>【<strong class=\"source-bold\">プロイセン＝フランス戦争</strong>】</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スペイン王位<ruby>継承<rt>けいしょう</rt></ruby>問題</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ホーエンツォレルン家のレオポルト</strong>をスペイン王に<ruby>推戴<rt>すいたい</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><strong class=\"source-bold\">エムス電報事件</strong>でビスマルクがナポレオン3世を挑発</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">普仏戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝フランス戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏戦争</strong></span>】［1870〜71］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">スダンの戦い</strong>［1870］……<strong class=\"source-bold\">ナポレオン3世を<ruby>捕虜<rt>ほりょ</rt></ruby></strong>とする</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ帝国</strong></span>成立［1871］……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ宮殿</strong></span>でドイツ皇帝の<ruby>戴冠式<rt>たいかんしき</rt></ruby>をおこなう</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">フランクフルト<ruby>講和<rt>こうわ</rt></ruby>条約</strong>［1871.5］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロレーヌ</strong></span>を<strong class=\"source-bold\">ドイツに<ruby>割譲<rt>かつじょう</rt></ruby></strong>／<span data-source-color=\"green\" style=\"color:#315837\">▶</span>50億フランの<strong class=\"source-bold\"><ruby>賠償金<rt>ばいしょうきん</rt></ruby></strong>を課す</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <strong class=\"source-bold\">普墺戦争と普仏戦争</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">普墺戦争の原因は？　シュレスヴィヒ・ホルシュタイン問題ってなんだろう</strong></span></h4>\n<p>まずは<strong class=\"source-bold\">オーストリアと戦争</strong>について見ていこう。オーストリアとの間には<strong class=\"source-bold\">ドイツの統一の主導権をめぐる対立</strong>はあるけど、すぐに戦争になるほどでもない。ただ、<strong class=\"source-bold\">きっかけがなければつくってしまえ！</strong>っていうのがビスマルクなんだよ。最終的にプロイセンとオーストリアは戦争に突入するんだけど、開戦の契機となったのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュレスヴィヒ・ホルシュタイン問題</strong></span>だ。</p>\n<p>ユトランド半島の付け根に位置する<strong class=\"source-bold\">シュレスヴィヒ公国とホルシュタイン公国</strong>には<strong class=\"source-bold\">ドイツ人が住んで</strong></p>\n<blockquote><p>気づいたときにはすでに、オーストリアは戦争に引きずりこまれてるよ</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "84": "<h2>84</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p><strong class=\"source-bold\">いて</strong>、両国は古くから<ruby>不可分<rt>ふかぶん</rt></ruby>（分割しちゃダメ）な地域とされ、15世紀以降は<strong class=\"source-bold\">デンマークが同君連合として支配</strong>していた（別々の国だけど、国王は一緒ってことだよ）。そしてウィーン体制下ではホルシュタインがドイツ連邦に参加していたんだけど、1863年に<strong class=\"source-bold\">デンマークがシュレスヴィヒを<ruby>併合<rt>へいごう</rt></ruby></strong>したんだ。これには<strong class=\"source-bold\">ドイツ系住民が怒った</strong>。そしてドイツ連邦に「デンマークをなんとかしてくれ〜」って頼んだ。この要請を受けて<strong class=\"source-bold\">プロイセンとオーストリアが共同出兵</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デンマーク戦争</strong></span>が始まったんだけど、この時ビスマルクは「<strong class=\"source-bold\">オーストリアと開戦するのに使える</strong>」って思ったんだ。</p>\n<p>ビスマルクは、「皇帝ならばドイツ人を助けるべきだ！」とおだてて<strong class=\"source-bold\">オーストリアを参戦させ</strong>、プロイセン軍は本気を出さなかった。だって、<strong class=\"source-bold\">プロイセン・オーストリア連合軍ならばほぼ勝てる</strong>。そして、オーストリア軍がどのくらいの強さかを調べさせ、「99％勝てるな」って確信したんだ。これならいつ<ruby>普墺<rt>ふおう</rt></ruby>戦争に突入しても大丈夫だけど、ここからさらに手を打つのがビスマルクの怖いところ。<strong class=\"source-bold\">フランスのナポレオン3世には中立を約束させる</strong>ために「ライン左岸のどこかを<ruby>割譲<rt>かつじょう</rt></ruby>」するとの口約束を与え、<strong class=\"source-bold\">さらにイタリアを味方にした</strong>。これでほぼ100％。そこまでやるか……。</p>\n<p>デンマークに勝ったあと、<strong class=\"source-bold\">シュレスヴィヒはプロイセン、ホルシュタインはオーストリア</strong>が<ruby>統治<rt>とうち</rt></ruby>することになったんだけど、<strong class=\"source-bold\">ビスマルクは</strong>「オーストリアはちゃんと統治していない！」といちゃもんをつけて<strong class=\"source-bold\">オーストリアを挑発</strong>し、まんまと開戦に持ち込んだ。こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">普墺戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝オーストリア戦争</strong></span>】が始まったんだ。この時すでに<strong class=\"source-bold\">プロイセンは北ドイツの<ruby>領邦<rt>りょうほう</rt></ruby>と同盟</strong>を結んでいたから、実際は<strong class=\"source-bold\">親プロイセン派と親オーストリア派によるドイツ連邦内の戦争</strong>って考えることもできるよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">普墺戦争は、あっという間にプロイセンの勝利！</strong></span></h4>\n<p>普墺戦争は、最初から結果が見えてるよ。だって、ビスマルクは100％勝てるように準備したんだもん。<strong class=\"source-bold\">鉄道や電信</strong>などの最新技術を駆使してあっという間に軍隊を移動させ、<strong class=\"source-bold\">サドヴァの戦い</strong>【<strong class=\"source-bold\">ケーニヒグレーツの戦い</strong>】で圧勝すると、そのまま<strong class=\"source-bold\">ベーメンを制圧</strong>した。この時、軍部はウィーンに進軍するって言ったんだけど、ビスマルクは講和を結んだよ。これまたビスマルクのすごい作戦だ。</p>\n<p>こうして結ばれた<strong class=\"source-bold\">プラハ条約</strong>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュレスヴィヒ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホルシュタイン</strong></span><strong class=\"source-bold\">両公国のプロイセンへの併合とドイツ連邦の解体</strong>、さらに<strong class=\"source-bold\">ドイツ統一問題へのオーストリアの<ruby>不干渉<rt>ふかんしょう</rt></ruby></strong>が決まったよ。これ以後、統一の主導権は完全にプロイセンが握るんだけど、この条約の何がすごいか、全然わかんない！ってなってるでしょ？</p>\n<p>普墺戦争で<strong class=\"source-bold\">オーストリアが失った領土</strong>はどこか？　<strong class=\"source-bold\">ホルシュタインだけ</strong>だよね。プロイセンは戦争中にベーメンを<ruby>占領<rt>せんりょう</rt></ruby>し、ウィーンにだって攻め込めた。本当ならベーメンの割譲も要求できる。でも、オーストリア皇帝のプライドが丸<ruby>潰<rt>つぶ</rt></ruby>れになるからウィーンは占領しなかったし、ベーメンもオーストリアに返した。これ全部</p>",
  "85": "<h2>85</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">普墺戦争と普仏戦争</u></p>\n<p>「<strong class=\"source-bold\">次にフランスと戦争するときに、オーストリアを敵にしないため</strong>」だ。「ベーメンは返します」って言われて、オーストリアは「こりゃビスマルクにはかなわない」って思ってしまったから、このあと<strong class=\"source-bold\">プロイセン</strong>（<strong class=\"source-bold\">統一後はドイツ</strong>）<strong class=\"source-bold\">とオーストリアはずっと仲が良い</strong>んだ。ビスマルクって怖いでしょ。</p>\n<p>こうして勝利したプロイセンは、<strong class=\"source-bold\">22カ国</strong>（3自由市を含む）を統合して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ドイツ連邦</strong></span>を結成したよ。これは<strong class=\"source-bold\">事実上のドイツ統一</strong>だけど、カトリックの<strong class=\"source-bold\">バイエルンなどが入っていない</strong>し<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➜P.82地図</span>、国際的にはフランスが反対しているから、正式に統一とは言わなかったんだね。</p>\n<blockquote><p>ドイツ連邦のなかで一番南にあったのがオーストリアだ。それを抜かせば北ドイツ連邦だね</p></blockquote>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目　ドイツ連邦と北ドイツ連邦</strong></h4>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ連邦</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィーン<ruby>議定書<rt>ぎていしょ</rt></ruby></strong></span>で成立したドイツの国家連合</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア</strong></span>を議長国とする<strong class=\"source-bold\">35君主国と4自由市</strong>の連合体</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">普墺戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝オーストリア戦争</strong></span>】の<strong class=\"source-bold\">プラハ条約</strong>で解体</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ドイツ連邦</strong></span>……<strong class=\"source-bold\">普墺戦争後に成立した</strong>国家連合。事実上のドイツ統一</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン</strong></span>を首長とする、<strong class=\"source-bold\">マイン川以北の22君主国</strong>の連合体</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">オーストリアを排除</strong>し、親オーストリアの<strong class=\"source-bold\">バイエルンなども不参加</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➜</span>1871年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ帝国</strong></span>成立で、発展的に解消</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">オーストリアの支配が弱まって……オーストリア＝ハンガリー帝国が成立！</strong></span></h4>\n<p>普墺戦争後、<strong class=\"source-bold\">オーストリア領内では大問題が発生</strong>していたよ。戦争に負けたことで、ドイツ人のオーストリア政府（要するにハプスブルク家ね）が弱いのがバレちゃった。だから、これまでずっと我慢してきた<strong class=\"source-bold\">領内の諸民族が反抗し始めた</strong>んだよ。しかも、多民族国家オーストリアでは<strong class=\"source-bold\">ドイツ人以外のほうが、圧倒的に人口が多い</strong>（ドイツ人は全人口の約4分の1）……こりゃマズいことになったね。</p>\n<p>しかし、そこはあの手この手で皇帝位を守ってきた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハプスブルク家</strong></span>、すごい裏ワザを思いついた。それが「ハンガリーの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マジャール人</strong></span>にだけ自治権を与えて、味方につける」って作戦。マジャール人はオーストリア領内の最大の異民族（全人口の約2割）だから、<strong class=\"source-bold\">ドイツ人とマジャール人が手を組んで、他の民族運動を抑え込もう</strong>ってことだ。そこで、<strong class=\"source-bold\">ハンガリー王国の自治権を認め</strong>（内政上の支配権を持つハンガリー政府とハンガリー議会ができるよ）、<strong class=\"source-bold\">ハンガリー王位はオーストリア皇帝が兼任</strong>することになった。このハンガリーとの<ruby>妥協<rt>だきょう</rt></ruby>【<strong class=\"source-bold\">アウスグライヒ</strong>】によって、</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "86": "<h2>86</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア＝ハンガリー</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">二重</strong></span>）<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国</strong></span>が成立したよ。</p>\n<h4><strong class=\"source-bold\">〈オーストリア＝ハンガリー帝国〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア皇帝　＝　ハンガリー国王</strong></span></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">（ハプスブルク家）</span></td><td></td></tr><tr><td><strong class=\"source-bold\">オーストリア帝国</strong></td><td><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ハンガリー王国</strong></span></td></tr><tr><td><strong class=\"source-bold\">オーストリア政府</strong></td><td><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ハンガリー政府</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共通閣議も実施</strong></span></td><td></td></tr><tr><td><strong class=\"source-bold\">オーストリア帝国議会</strong></td><td><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ハンガリー王国議会</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共通会議も実施</strong></span></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">（オーストリア代表60名、ハンガリー代表60名）</span></td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">次はフランスを<ruby>挑発<rt>ちょうはつ</rt></ruby>……スペイン王位<ruby>継承<rt>けいしょう</rt></ruby>問題ってなんだ？</strong></span></h4>\n<p>さて、次は<strong class=\"source-bold\">フランスとの戦争</strong>だ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span>はプロイセンに反発する南ドイツのバイエルンなどに働きかけて、<strong class=\"source-bold\">ドイツ統一を妨害してきた</strong>。これは<strong class=\"source-bold\">メキシコ出兵の失敗で国内の人気が落ちていた</strong>ことが背景だね。さらにビスマルクが「ライン左岸<ruby>割譲<rt>かつじょう</rt></ruby>」の口約束を無視したのも原因だ。ビスマルクは、いつでもフランスと戦争できるように準備を進めていたけど、すぐにその時がきた。きっかけは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スペイン王位継承問題</strong></span>だ。</p>\n<p><strong class=\"source-bold\">スペイン</strong>はかつてのフランス王家と同じ<strong class=\"source-bold\">ブルボン家</strong>だったから、フランスとの仲は悪くない。ところが1868年の革命でイサベル2世が<ruby>亡命<rt>ぼうめい</rt></ruby>して<strong class=\"source-bold\">ブルボン朝が倒れる</strong>と、<strong class=\"source-bold\">ホーエンツォレルン家</strong>（<strong class=\"source-bold\">プロイセン王家の遠縁</strong>）<strong class=\"source-bold\">のレオポルトが新しいスペイン王位に<ruby>推戴<rt>すいたい</rt></ruby></strong>され、ビスマルクも受諾するよう働きかけた。これはフランスにとってはタダ事じゃない！　だって、<strong class=\"source-bold\">プロイセン王家に挟み撃ち</strong>にされちゃうよ。これは16世紀に<strong class=\"source-bold\"><ruby>神聖<rt>しんせい</rt></ruby>ローマ皇帝カール5世がスペイン王位を兼任</strong>してフランスが挟み撃ちになった悪夢の再来だ。あまりのフランスの反発に、<strong class=\"source-bold\">レオポルトは王位を辞退</strong>したから、これで解決！　と思ったら、このあとのナポレオン3世の対応がまずかった……。ビスマルクの<ruby>罠<rt>わな</rt></ruby>にはまったんだ。</p>\n<p>ナポレオン3世は「プロイセン王家からは二度とスペイン王位を出さない」という確約をとろうと、<strong class=\"source-bold\">プロイセン国王ヴィルヘルム1世</strong>が静養している<strong class=\"source-bold\">温泉地エムスに特使を派遣</strong>したんだけど、すでに国王位の辞退で譲歩していたから、<strong class=\"source-bold\">ヴィルヘルム1世はこの申し入れを拒否</strong>し、ベルリンにいるビスマルクにこの経緯を電報で伝えたんだ。これを聞いたビスマルクは、<strong class=\"source-bold\">開戦に利用しようと内容を変えて発表</strong>した</p>",
  "87": "<h2>87</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">普墺戦争と普仏戦争</u></p>\n<p>……「フランス大使の無礼に怒ったヴィルヘルム1世は、今後一切フランスとは交渉しない」ってね。この<strong class=\"source-bold\">エムス電報事件</strong>によって<strong class=\"source-bold\">開戦の世論が高揚</strong>、プロイセンでは「フランスと開戦しろ！」って大騒ぎになり、フランスでもパリ民衆が「こんな<ruby>侮辱<rt>ぶじょく</rt></ruby>は許せん！　開戦しろ〜」と激怒して反乱寸前！　<strong class=\"source-bold\">人気が落ち目の</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span><strong class=\"source-bold\">は<ruby>宣戦<rt>せんせん</rt></ruby>布告</strong>するしかなかったんだよ。こうして1870年7月、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝フランス戦争</strong></span>】が<ruby>勃発<rt>ぼっぱつ</rt></ruby>した。この戦争、すでに<strong class=\"source-bold\">北ドイツ連邦と南ドイツの<ruby>領邦<rt>りょうほう</rt></ruby>がプロイセン軍とともに出兵</strong>してるから、実態は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏戦争</strong></span>だね。</p>\n<blockquote><p>エムス電報事件……当時は電報が一番速い通信手段だったけど、今じゃネットやテレビがあるから、不可能な事件だな</p></blockquote>\n<h4><strong class=\"source-bold\">〈イタリア・ドイツの統一後のヨーロッパ〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ノルウェー</strong></td><td><strong class=\"source-bold\">スウェーデン</strong></td></tr><tr><td><strong class=\"source-bold\">デンマーク</strong></td><td><strong class=\"source-bold\">イギリス</strong></td></tr><tr><td><strong class=\"source-bold\">オランダ</strong></td><td><strong class=\"source-bold\">ベルギー</strong></td></tr><tr><td><strong class=\"source-bold\">○ベルリン</strong></td><td><strong class=\"source-bold\">ドイツ帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ロシア帝国</strong></td><td>○パリ</td></tr><tr><td><strong class=\"source-bold\">フランス共和国</strong></td><td><strong class=\"source-bold\">○プラハ</strong></td></tr><tr><td><strong class=\"source-bold\">○ウィーン</strong></td><td><strong class=\"source-bold\">スイス</strong></td></tr><tr><td>アルザス・ロレーヌ</td><td><strong class=\"source-bold\">オーストリア＝ハンガリー帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ポルトガル</strong></td><td><strong class=\"source-bold\">スペイン王国</strong></td></tr><tr><td><strong class=\"source-bold\">イタリア王国</strong></td><td></td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "88": "<h2>88</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">2</span></h3>\n<h4><strong class=\"source-bold\">〜近代国家の建設〜</strong></h4>\n<p>江戸時代までの日本は幕藩体制と呼ばれる封建的な支配体制で、国内は各地の大名が支配する領地（藩）に分かれていて、幕府が直接支配できるのは<ruby>直轄地<rt>ちょっかつち</rt></ruby>だけだった。西欧の封建制と似ているよね。また、人びとの身分も固定されていて、武士が支配階級で、支配される側も農民（百姓）、商人・職人（町人）に分かれていた。日本もこうした身分制社会だったんだよ。</p>\n<p>明治新政府は近代国家の建設を進めたよ。まずは江戸時代までの<strong class=\"source-bold\">身分制度を解体</strong>し、大名・公家を華族、武士を士族、百姓・町人を平民と改称して、さらに華族・士族・平民の結婚や、移住・職業選択の自由などが認められたんだ。武士身分が廃止されたから、1873年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>徴兵<rt>ちょうへい</rt></ruby>制度</strong></span>が導入されて、兵役は国民の義務になった。また、財政の安定のために、個人の土地所有権を認めたうえで、年貢にかえて<strong class=\"source-bold\">土地税を金納で納めさせる</strong>ことにした（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>地租改正<rt>ちそかいせい</rt></ruby></strong></span>）。</p>\n<p>一方で、国際的には江戸時代に結んだ<strong class=\"source-bold\">不平等条約の改正</strong>を目指したよ。1871年には<strong class=\"source-bold\"><ruby>岩倉具視<rt>いわくらともみ</rt></ruby></strong>を代表に、<ruby>大久保利通<rt>おおくぼとしみち</rt></ruby>、<ruby>伊藤博文<rt>いとうひろぶみ</rt></ruby>ら政府の中心人物を<strong class=\"source-bold\">欧米に派遣した</strong>けど、このころの日本は、まだ近代的な国家制度が整っていなかったから、相手にされなかった。この時、実際に欧米諸国を見た大久保や伊藤は「<strong class=\"source-bold\">日本は本当に遅れている！</strong>」と痛感して、欧米に追いつくために近代化を加速したんだ。また、欧米の思想を学んだ知識人（<strong class=\"source-bold\"><ruby>福沢諭吉<rt>ふくざわゆきち</rt></ruby></strong>・<strong class=\"source-bold\"><ruby>中江兆民<rt>なかえちょうみん</rt></ruby></strong>など）は、新しい国家のあり方を主張し始めた。彼らのなかから民主化を求める<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由民権運動</strong></span>が始まり、また政府も近代国家建設のため、<strong class=\"source-bold\">憲法の制定と議会の開設を目指した</strong>んだ。</p>\n<p>結果、政府は君主権が強い<strong class=\"source-bold\">プロイセン憲法をモデル</strong>に憲法を制定することとした。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">伊藤博文</strong></span>をヨーロッパに派遣し、ドイツなどで政治や法律などを調査した。帰国した伊藤を中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">内閣制度</strong></span>を設置すると、さらに1889年、<strong class=\"source-bold\">天皇が定める<ruby>欽定<rt>きんてい</rt></ruby>憲法</strong>として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大日本帝国憲法</strong></span>が発布された。この憲法では、天皇は主権者としてすべての統治権（天皇大権）を持ったけど、その権限は内閣や帝国議会などの各機関を通じて行使することになっていた（<strong class=\"source-bold\">立憲君主政</strong>）。例えば、法律や予算の成立には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国議会</strong></span>（貴族院・衆議院）の同意が必要だったからね。ただ、この時点で選挙権を持っていたのは、一定の税金を納める25歳以上の男性のみで（制限選挙）、全人口の1％程度だったんだ。</p>\n<p>国会が開設されたといっても、<strong class=\"source-bold\">内閣は<ruby>薩摩<rt>さつま</rt></ruby>・<ruby>長州<rt>ちょうしゅう</rt></ruby>出身の有力政治家で固められていた</strong>んだけど（藩閥政府）、衆議院では選挙のたびに民権派の政党が優勢になったから、政府も政党を無視できなくなった。この結果、1898年には<strong class=\"source-bold\">初の政党内閣</strong>（憲政党の<strong class=\"source-bold\"><ruby>大隈重信<rt>おおくましげのぶ</rt></ruby></strong>内閣）が成立したんだ。</p>",
  "89": "<h2>89</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">6</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">統一後のドイツ</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争はプロイセンの圧勝！　ついにドイツ帝国の成立だ</strong></span></h4>\n<p>ここまで<strong class=\"source-bold\">万全の開戦準備をしていたビスマルク</strong>は、<strong class=\"source-bold\">フランスをメッタメタに倒す</strong>つもりだ。新型の兵器で武装した50万以上のプロイセン軍は連戦連勝、もはやフランスに勝ち目はない。プロイセン軍は<strong class=\"source-bold\">アルザス・ロレーヌに<ruby>侵攻<rt>しんこう</rt></ruby></strong>し、<strong class=\"source-bold\">スダンの戦い</strong>では<strong class=\"source-bold\">ナポレオン3世を<ruby>捕虜<rt>ほりょ</rt></ruby></strong>にした。さらに9月には<strong class=\"source-bold\">パリも包囲</strong>して、極めつけはフランス人のプライドまでズタズタにした。1871年1月<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ宮殿</strong></span>に乗りこんだプロイセン軍は、フランスの栄光の<ruby>象徴<rt>しょうちょう</rt></ruby>だった「<strong class=\"source-bold\"><ruby>鏡<rt>かがみ</rt></ruby>の<ruby>間<rt>ま</rt></ruby></strong>」で<strong class=\"source-bold\">ヴィルヘルム1世のドイツ皇帝<ruby>戴冠式<rt>たいかんしき</rt></ruby></strong>をやったんだよ。こうして、正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ帝国</strong></span><strong class=\"source-bold\">が成立</strong>したんだけど、いくらなんでもやりすぎだろ、ビスマルク。</p>\n<p>そして5月には、<strong class=\"source-bold\">フランクフルト<ruby>講和<rt>こうわ</rt></ruby>条約</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロレーヌ</strong></span><strong class=\"source-bold\">のドイツへの<ruby>割譲<rt>かつじょう</rt></ruby></strong>と50億フランの<strong class=\"source-bold\"><ruby>賠償金<rt>ばいしょうきん</rt></ruby>支払い</strong>が決まったんだ。領土を取られ、賠償金を課せられ、さらにプライドまで<ruby>潰<rt>つぶ</rt></ruby>されたフランス人は「<strong class=\"source-bold\">絶対ドイツは許さない！</strong>」と心底ドイツを<ruby>恨<rt>うら</rt></ruby>んだ。この<strong class=\"source-bold\">対独<ruby>復讐心<rt>ふくしゅうしん</rt></ruby></strong>がこのあとのフランス史に大きく影響するよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">6</span> <strong class=\"source-bold\">統一後のドイツ</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツ帝国ってどんな国になったんだろう？</strong></span></h4>\n<p>さて、ビスマルクの強力な指導力によって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム1世</strong></span>を<strong class=\"source-bold\">ドイツ皇帝</strong>【<strong class=\"source-bold\">カイザー</strong>】、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>を<strong class=\"source-bold\">帝国<ruby>宰相<rt>さいしょう</rt></ruby></strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ帝国</strong></span>が成立し、ヨーロッパの真ん中に大国ドイツが出現したけど、その中身は<strong class=\"source-bold\">帝国<ruby>直轄地<rt>ちょっかつち</rt></ruby></strong>（<strong class=\"source-bold\">プロイセンとアルザス・ロレーヌ</strong>ね）<strong class=\"source-bold\">と22の君主国、3つの自由市</strong>からなる連邦制国家で、<strong class=\"source-bold\">カトリックで親オーストリアのバイエルンなどが新たに加わった</strong>。ドイツ帝国ってドイツ国民によってつくられたというより、<strong class=\"source-bold\">ビスマルクが</strong>「<strong class=\"source-bold\"><ruby>鉄血<rt>てっけつ</rt></ruby>政策</strong>」、つまり<strong class=\"source-bold\">軍事力でつくった</strong>んだもん。しかも、普仏戦争では、北ドイツ連邦の君主国がプロイセン軍に協力していて、ドイツ帝国成立の布告にも「ドイツ<ruby>諸侯<rt>しょこう</rt></ruby>と諸都市の要請で皇帝になる」って書いてある。そうなると、帝国の<ruby>統治<rt>とうち</rt></ruby>は、<strong class=\"source-bold\">プロイセンを中心に各領邦の君主と妥協</strong>しながら政治を進めることになるね。</p>\n<p>こんな状況だから、ドイツの議会は<strong class=\"source-bold\">連邦参議院</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国議会</strong></span>の二院制になった。<strong class=\"source-bold\">連邦参議院</strong>は<strong class=\"source-bold\">君主国の代表</strong>、<strong class=\"source-bold\">帝国議会</strong>は<strong class=\"source-bold\">25歳以上の</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男性普通選挙</strong></span>で議員を選んだ。ん、普通選挙？　ビスマルクって自由とか平等とかキライじゃなかったっけ？　いやいや、男性普通選挙ってだけで平等と思っちゃいけない！　それは「選ばれた議会にちゃんと権限があれば」の話だ。帝国議会には<strong class=\"source-bold\">責任内閣制も認められないし</strong>、招集するのも皇帝が決める、<strong class=\"source-bold\">大した権限</strong>（予算審議権や質問権だけだよ）<strong class=\"source-bold\">はなかった</strong>。これじゃあ、とても平等だなんていえない</p>\n<blockquote><p>皇帝の力が強くて、議会の権限はほとんどなし……普通選挙もただの想い出だな</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "90": "<h2>90</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>ね。じゃあ、<strong class=\"source-bold\">なんで男性普通選挙にしたのか？</strong>　それはドイツ帝国内のすべての人に「ドイツの政治に参加してるから、私たちはドイツ国民だ」って思わせるためだよ。バラバラだったドイツ統合のために<strong class=\"source-bold\">普通選挙を利用して国民意識をつくった</strong>ってことだ。ただ、官僚の多くはユンカーの出身の貴族だからなぁ……。結局はもともとの支配階級が強いまま、<strong class=\"source-bold\">見た目を立憲君主政にした</strong>ってことだね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">プロイセン中心主義に反発したカトリック勢力。文化闘争が始まった！</strong></span></h4>\n<p>形としては統一を実現したドイツだったけど、<strong class=\"source-bold\">帝国を分裂させる要素</strong>はたくさんあったんだよ。特に、帝国の中心となった<strong class=\"source-bold\">プロイセンはプロテスタントの国</strong>だったから、カトリックの連中にしてみればおもしろくない。しかも、かつて<strong class=\"source-bold\">カトリックの中心だったのは統一から排除されたオーストリア</strong>だから、カトリック教徒は「オーストリア中心がよかったのに……」と思っている。しかも、帝国議会の選挙で<strong class=\"source-bold\">カトリック政党の中央党</strong>が議席を伸ばし（1871年の選挙ではなんと第2党だ！）、だんだん見逃せない状況になっていたんだね。こうしてビスマルクは、カトリックの聖職者を「帝国の敵」と呼び、<strong class=\"source-bold\">南ドイツを中心とするカトリック教会やカトリック政党</strong>、特に<strong class=\"source-bold\">中央党との対立</strong>を深め、ついには<ruby>弾圧<rt>だんあつ</rt></ruby>を始めた。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文化闘争</strong></span>は、1870年代後半からビスマルクが譲歩して収まり始めたんだけど、譲歩したのはもっとヤバい問題が起きたからだ。それが<strong class=\"source-bold\">社会主義の拡大</strong>だよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">社会主義者が台頭！　でも、労働者は敵に回せない。「アメとムチ」ってなんだ？</strong></span></h4>\n<p>統一後のドイツでは、ビスマルクが<strong class=\"source-bold\">国内産業の発展を優先</strong>して、しかもフランスからいっぱい<ruby>賠償金<rt>ばいしょうきん</rt></ruby>を取ったこともあって、<strong class=\"source-bold\">急激に工業が発展</strong>したよ。まあ、一種のバブル経済みたいな部分もあるけど、例えば製鉄会社の数が倍増したり、統一以前からある軍需産業の<strong class=\"source-bold\">クルップ社</strong>やジーメンス社がますます発展して、特に<strong class=\"source-bold\">重化学工業の生産が急増した</strong>。ってことは、<strong class=\"source-bold\">労働者階級が増えている</strong>ってことだよね。</p>\n<p>でも、1873年には<strong class=\"source-bold\">株価の暴落</strong>から<strong class=\"source-bold\">金融危機</strong>が起こり、しかもフランスからの賠償金も終わっちゃったから<strong class=\"source-bold\">深刻な経済<ruby>恐慌<rt>きょうこう</rt></ruby></strong>となって、労働者の生活も悪化した。だから「労働者を守れ〜」って主張する<strong class=\"source-bold\">社会主義者が男性普通選挙で選ばれ、議会に進出</strong>し始めた。すでに統一以前から、ラサールを指導者とする<strong class=\"source-bold\">全ドイツ労働者協会</strong>【<strong class=\"source-bold\">ラサール派</strong>】や、マルクスの弟子の<strong class=\"source-bold\">ベーベル</strong>を指導者とする<strong class=\"source-bold\">社会民主労働者党</strong>【<strong class=\"source-bold\">アイゼナハ派</strong>】などが活動していたんだけど、1875年には、彼らが一緒になって<strong class=\"source-bold\">世界最初の社会主義政党</strong>である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会主義労働党</strong></span>を結成、帝国議会でも勢力を拡大し始めた。</p>\n<p>もちろん、<strong class=\"source-bold\">帝国議会に大した権限はなかった</strong>けど、だからといって100％無視するわけにもいかないでしょ。そんなことをしたら国民全員を敵に回すことになる。だから<strong class=\"source-bold\">少しは議会の言うことに耳を傾ける</strong>よね。そうすると、社会主義者の言うことも聞かなきゃいけなくなる……。ビスマルクは焦った。「彼らを放置したら、いつか国家をひっくり返す勢力になる……」。そこで、1878年、<strong class=\"source-bold\">皇帝<ruby>狙撃<rt>そげき</rt></ruby>事件</strong>を口</p>",
  "91": "<h2>91</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">6</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">統一後のドイツ</u></p>\n<p>実に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義者<ruby>鎮圧<rt>ちんあつ</rt></ruby>法</strong></span>を制定して、<strong class=\"source-bold\">社会主義的な政党・出版・集会などを禁止</strong>としたんだ。これがいわゆる「<strong class=\"source-bold\">アメとムチ</strong>」の政策の「ムチ」の部分だ。「アメとムチ」ってのは、アメをなめさせるみたいに<strong class=\"source-bold\">保護する政策</strong>とムチで<ruby>叩<rt>たた</rt></ruby>くみたいに<strong class=\"source-bold\">厳しい政策</strong>を一緒にやるってことだよ。</p>\n<p>さて、ここで問題になるのが労働者の気持ち。社会主義者は「労働者を守ろう！」って言ってるから、労働者たちは社会主義者を自分たちの味方だと思ってる。だから、<strong class=\"source-bold\">社会主義者が<ruby>弾圧<rt>だんあつ</rt></ruby>されると、自分たちも弾圧される</strong>んじゃないかってビビってるんだ。そうなると労働者たちはビスマルク、さらにはドイツ帝国のことがキライになる。でもね、<strong class=\"source-bold\">ビスマルクは労働者を敵に回したくない</strong>んだよ。だって、ドイツ帝国の発展のためには労働者に<ruby>頑張<rt>がんば</rt></ruby>って働いてもらわなきゃいけない。そこで「<strong class=\"source-bold\">アメ</strong>」<strong class=\"source-bold\">の登場</strong>！　ビスマルクは、社会主義者鎮圧法を制定する一方、<strong class=\"source-bold\">労働者に対する</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会保険制度</strong></span>を導入して<strong class=\"source-bold\">彼らの生活を守る</strong>姿勢を示した。この時に<strong class=\"source-bold\"><ruby>疾病<rt>しっぺい</rt></ruby>保険</strong>や<strong class=\"source-bold\">災害保険</strong>、<strong class=\"source-bold\"><ruby>養老<rt>ようろう</rt></ruby>保険</strong>なんかがつくられたんだけど、これって「病気になったり災害にあったり歳を取ったり、労働者の皆さんが生活に困ったら国が守ってあげるから、社会主義者とは手を切りなさい」ってことだ。教科書みたいな言葉を使うと、<strong class=\"source-bold\">労働者を社会主義者から分離</strong>して、国家が統制しようとした、ってことだ。</p>\n<blockquote><p>社会主義者は「敵」として弾圧、労働者は「味方」にするために保護する、これが「アメとムチ」ね</p></blockquote>\n<p>こうして国家の統合を最優先に、ビスマルクはドイツ帝国の発展に努めたよ。国内産業は<strong class=\"source-bold\">保護貿易政策</strong>にも守られて、急激に発展していったんだね。あっ、ドイツの場合は、<strong class=\"source-bold\">新興の産業資本家と伝統的なユンカー</strong>（彼らは地主だよ）<strong class=\"source-bold\">の保護</strong>のために、工業製品にも農産物にも輸入<ruby>関税<rt>かんぜい</rt></ruby>をかける<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保護関税法</strong></span>をつくった。工業は先進国イギリスに対抗しなきゃいけないし、農業はロシアなどの安い穀物に対抗しなきゃいけないもんね。こうした政策は「<strong class=\"source-bold\">鉄と穀物の同盟</strong>」なんて呼ばれているよ。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">フランスを孤立させるビスマルク体制って？</strong></span></h4>\n<p>ここまではドイツの国内問題を中心に見てきたけど、最後に<strong class=\"source-bold\">対外的な問題</strong>を話しておこう。統一後の対外関係で、とにかく危ないのは<strong class=\"source-bold\">フランスの<ruby>復讐心<rt>ふくしゅうしん</rt></ruby></strong>だよ。フランス人はドイツをかなり<ruby>恨<rt>うら</rt></ruby>んでるから、いつ攻めてきてもおかしくない。それなら、フランスに備えるために軍隊をバンバン増やすか、っていうとそうもいかないよ。だって、一応<strong class=\"source-bold\">議会の言うことも少しは聞かなきゃいけない</strong>し、それ以上に、<strong class=\"source-bold\">国内発展にお金がかかる</strong>でしょ。じゃあ、フランスに対してはどうするか？　それをなんとかするのは外交だよ。</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク体制</strong></span>とも呼ばれる彼が作った国際秩序は、とにかく<strong class=\"source-bold\">フランスを孤立</strong>させるために、<strong class=\"source-bold\">ヨーロッパ列強の勢力<ruby>均衡<rt>きんこう</rt></ruby></strong>を図り、フランス以外の国と全部仲良くす</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "92": "<h2>92</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第4回</strong></span> イタリア・ドイツの統一</p>\n<p>るっていう国際体制だ。ここでは<strong class=\"source-bold\">オーストリアとの同盟</strong>を軸に、<strong class=\"source-bold\">ロシアとは友好関係</strong>を維持しながら、<strong class=\"source-bold\">イギリスの好意</strong>を得る。ドイツが植民地を取ろうとすると他の国との対立が起こるから、<strong class=\"source-bold\">なるべく領土拡大はしない</strong>。こうした方針のもとで、フランスを孤立させることに成功し、ドイツの安全を確保したんだよ。ビスマルク体制については、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span>で詳しく解説するね。</p>\n<h4><strong class=\"source-bold\">〈ビスマルク体制〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">英</strong></td><td><strong class=\"source-bold\">「光栄ある孤立」</strong></td></tr><tr><td><strong class=\"source-bold\">仏</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">伊</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">墺</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約［1887］</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三帝同盟［1873・1881］</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">三国同盟［1882］</strong></span></td></tr></tbody></table></div>\n<blockquote><p>フランスはビスマルクに完全に孤立させられたよ</p></blockquote>\n<p>これでイタリアとドイツの統一はおしまい。それじゃあ、最後に年号 check！</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">!!</strong></span><span data-source-color=\"red\" data-source-background=\"white\" style=\"color:#e52715;background-color:#ffffff\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">クリミア戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1853</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>誤<rt>5</rt></ruby><ruby>算<rt>3</rt></ruby></strong></span>の　クリミア戦争）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">イタリア王国の成立</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1861</strong></span>］（みんなで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>や<rt>8</rt></ruby><ruby>ろ<rt>6</rt></ruby></strong></span>う　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>イ<rt>1</rt></ruby></strong></span>タリア統一）</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">➜</span><strong class=\"source-bold\">アメリカの南北戦争、ロシアの<ruby>農奴<rt>のうど</rt></ruby>解放令</strong>と同じ年だ！</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>普墺<rt>ふおう</rt></ruby>戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1866</strong></span>］（オーストリアが勝つ？　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>や<rt>8</rt></ruby><ruby>無<rt>6</rt></ruby></strong></span>理<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無<rt>6</rt></ruby></strong></span>理）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1870</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>火<rt>1</rt></ruby><ruby>花<rt>87</rt></ruby><ruby>を<rt>0</rt></ruby></strong></span>散らした　普仏戦争）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ドイツ帝国の成立</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1871</strong></span>］（統一で　ビスマルクが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>番<rt>8</rt></ruby><ruby>泣<rt>7</rt></ruby><ruby>い<rt>1</rt></ruby></strong></span>た）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">社会主義者<ruby>鎮圧<rt>ちんあつ</rt></ruby>法</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1878</strong></span>］（ビスマルク　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>イ<rt>1</rt></ruby><ruby>ヤ<rt>8</rt></ruby><ruby>な<rt>7</rt></ruby><ruby><ruby style=\"ruby-position:under\">奴<rt><span data-source-color=\"red\" style=\"color:#e52715\">ヤ</span><span data-source-color=\"black\" style=\"color:#222222\">ツ</span></rt></ruby><rt>8</rt></ruby></strong></span>）</p></blockquote>\n<p>次回は<strong class=\"source-bold\">ロシア</strong>だよ。19世紀は<strong class=\"source-bold\">イギリスとロシアがずっと対立</strong>しているんだよね……。最強国イギリスを敵に回しちゃったロシアはどうなっちゃうんだろ？</p>\n<p>そろそろペースがつかめてきたかな？　<ruby>頑張<rt>がんば</rt></ruby>っていこう〜。</p>"
};

